CREATE VIEW dq_external_rating_conflicts AS SELECT GameID, GameEditionID, RatingSourceID, RatingTypeID, count_star() AS source_row_count, min(RawRatingValue) AS min_raw_rating, max(RawRatingValue) AS max_raw_rating, min(RatingValue) AS min_rating, max(RatingValue) AS max_rating FROM stg_external_rating_normalized GROUP BY GameID, GameEditionID, RatingSourceID, RatingTypeID HAVING ((count_star() > 1) AND ((min(RatingValue) != max(RatingValue)) OR (min(RawRatingValue) != max(RawRatingValue))));
